var meter = new Meter("integration.control");
var processed = meter.CreateCounter<long>("messages.processed");

builder.Services.AddHealthChecks().AddCheck<QueueDepthCheck>("queue-depth");
builder.Services.AddSingleton<CommandHandler>();       // dispatcher shared by all command endpoints

var app = builder.Build();
app.MapHealthChecks("/healthz").RequireAuthorization();
app.MapPost("/admin/routes/{id}/suspend", (string id, CommandHandler h) => h.SuspendAsync(id))
   .RequireAuthorization("ops");
app.MapPost("/admin/stop", (IHostApplicationLifetime life) => { life.StopApplication(); return Results.Ok(); })
   .RequireAuthorization("ops");
app.Run();

