public interface IControlClient { Task Command(ControlCommand cmd); Task Status(StatusReport s); }

public sealed class ControlHub : Hub<IControlClient> {
    public Task Ack(string id, bool applied) => audit.RecordAsync(id, applied, Context.UserIdentifier);
    public Task Snapshot(StatusReport s) => Clients.Group("console").Status(s);
}
